//! The block-lattice family exercised end to end through provider
//! dispatch: `blockLatticeWF` and `productLatticeChecks` — spec
//! battery on the Kalies–Wehbe product witness (the two
//! one-dimensional flows with gridline cuts at 1/4 and 1/3, the same
//! instance the family format's fixture producer was built around),
//! named data mutants (every mutant flips a verdict), refusals, and
//! the frozen cross-implementation corpus replay
//! (`fixtures/bllattice_pyref_corpus.json`, generated by the
//! independent python reference `fixtures/bllattice_pyref_gen.py`).
//!
//! The test-side row emitter shares no code with the evaluators: it
//! writes `Op::Funa` field rows and `Op::Rela` membership rows
//! directly from the synthetic declaration index, and in the corpus
//! replay its facet counts and composite block lists come from the
//! python reference rather than from any Rust computation — the
//! evaluator's own recompute either agrees (the verdict holds) or the
//! corpus catches the divergence.

mod common;

use common::{ev_elems, provider, stack, STACK};
use geolog_envelope::body::Op;
use geolog_envelope::{ElemRef, Literal, Value};
use qtsl_geolog_provider::rowctx::CertRows;
use qtsl_geolog_provider::theory::Chid;
use serde_json::Value as J;

const OWN: [u8; 32] = [0xB7; 32];

fn s_fun(name: &str) -> Chid {
    stack()
        .fun(name)
        .unwrap_or_else(|| panic!("stack fun `{name}`"))
        .chid
}

fn lref(e: u32) -> Value {
    Value::Ref(ElemRef::Local(e))
}

fn natv(n: u64) -> Value {
    Value::Lit(Literal::nat(n))
}

fn qv(q: (i64, u64)) -> Value {
    Value::Lit(Literal::q(q.0, q.1).expect("canonical Q"))
}

// ---------------------------------------------------------------------
// The test-side emitter
// ---------------------------------------------------------------------

struct Body {
    ops: Vec<Op>,
    next: u32,
    deps: Vec<[u8; 32]>,
}

impl Body {
    fn new() -> Body {
        Body {
            ops: Vec::new(),
            next: 0,
            deps: vec![STACK],
        }
    }

    fn xref(&self, c: Chid) -> ElemRef {
        let dep_index = self
            .deps
            .iter()
            .position(|d| *d == c.0)
            .expect("chid homed in a dep") as u32;
        ElemRef::External {
            dep_index,
            counter: c.1,
        }
    }

    fn fresh(&mut self) -> u32 {
        let e = self.next;
        self.next += 1;
        e
    }

    fn funa(&mut self, fun: &str, args: Vec<Value>, value: Value) {
        self.ops.push(Op::Funa {
            fun: self.xref(s_fun(fun)),
            args,
            value,
        });
    }

    fn rela(&mut self, rel: &str, args: Vec<Value>) {
        self.ops.push(Op::Rela {
            rel: self.xref(s_fun(rel)),
            args,
        });
    }

    /// A constructor row producing a fresh element.
    fn ctor(&mut self, fun: &str, args: Vec<Value>) -> u32 {
        let e = self.fresh();
        self.funa(fun, args, lref(e));
        e
    }

    fn rows(&self) -> CertRows {
        CertRows::from_ops(&self.ops, OWN, &self.deps)
    }
}

/// Scalar term trees, mirroring the wire fragment plus the
/// out-of-fragment constructors the mutants need.
#[derive(Clone)]
enum T {
    V(u32),
    C(i64, u64),
    Add(Box<T>, Box<T>),
    Mul(Box<T>, Box<T>),
    Sub(Box<T>, Box<T>),
    Neg(Box<T>),
}

fn add(l: T, r: T) -> T {
    T::Add(Box::new(l), Box::new(r))
}
fn mul(l: T, r: T) -> T {
    T::Mul(Box::new(l), Box::new(r))
}
fn sub(l: T, r: T) -> T {
    T::Sub(Box::new(l), Box::new(r))
}

impl Body {
    fn term(&mut self, t: &T) -> u32 {
        match t {
            T::V(w) => self.ctor("TVar", vec![lref(*w)]),
            T::C(n, d) => {
                let q = qv((*n, *d));
                self.ctor("TConst", vec![q])
            }
            T::Add(l, r) => {
                let (l, r) = (self.term(l), self.term(r));
                self.ctor("TAdd", vec![lref(l), lref(r)])
            }
            T::Mul(l, r) => {
                let (l, r) = (self.term(l), self.term(r));
                self.ctor("TMul", vec![lref(l), lref(r)])
            }
            T::Sub(l, r) => {
                let (l, r) = (self.term(l), self.term(r));
                self.ctor("TSub", vec![lref(l), lref(r)])
            }
            T::Neg(i) => {
                let i = self.term(i);
                self.ctor("TNeg", vec![lref(i)])
            }
        }
    }
}

/// Pure tree substitution: `wire := value`, no simplification.
fn subst(t: &T, wire: u32, value: (i64, u64)) -> T {
    match t {
        T::V(w) if *w == wire => T::C(value.0, value.1),
        T::V(w) => T::V(*w),
        T::C(n, d) => T::C(*n, *d),
        T::Add(l, r) => add(subst(l, wire, value), subst(r, wire, value)),
        T::Mul(l, r) => mul(subst(l, wire, value), subst(r, wire, value)),
        T::Sub(l, r) => sub(subst(l, wire, value), subst(r, wire, value)),
        T::Neg(i) => T::Neg(Box::new(subst(i, wire, value))),
    }
}

/// One lattice's specification on the emitter side.
#[derive(Clone)]
struct LatSpec {
    wires: Vec<u32>,
    drifts: Vec<T>,
    /// Per axis, the gridlines as rationals.
    gridlines: Vec<Vec<(i64, u64)>>,
    /// Per block, strictly increasing cell indices.
    blocks: Vec<Vec<u64>>,
    /// Per block, the facet-proof elements in canonical slot order.
    facet_proofs: Vec<Vec<u32>>,
    /// Per block, an optional override of the declared facet count
    /// (`None` = the length of the proof list).
    n_facets_override: Vec<Option<u64>>,
}

impl LatSpec {
    fn new(
        wires: Vec<u32>,
        drifts: Vec<T>,
        gridlines: Vec<Vec<(i64, u64)>>,
        blocks: Vec<Vec<u64>>,
        facet_proofs: Vec<Vec<u32>>,
    ) -> LatSpec {
        let n = blocks.len();
        LatSpec {
            wires,
            drifts,
            gridlines,
            blocks,
            facet_proofs,
            n_facets_override: vec![None; n],
        }
    }
}

impl Body {
    /// Emit a full lattice: the entity element, its axes (index, wire,
    /// drift, gridlines), and its stored blocks (index, cells, facet
    /// counts and proof slots).
    fn lattice(&mut self, spec: &LatSpec) -> u32 {
        let bl = self.fresh();
        self.funa(
            "BlockLattice/nAxes",
            vec![lref(bl)],
            natv(spec.wires.len() as u64),
        );
        self.funa(
            "BlockLattice/nBlocks",
            vec![lref(bl)],
            natv(spec.blocks.len() as u64),
        );
        for (i, wire) in spec.wires.iter().enumerate() {
            let ax = self.fresh();
            self.funa("BLAxis/lattice", vec![lref(ax)], lref(bl));
            self.funa("BLAxis/index", vec![lref(ax)], natv(i as u64));
            self.funa("BLAxis/wire", vec![lref(ax)], lref(*wire));
            let drift = self.term(&spec.drifts[i].clone());
            self.funa("BLAxis/drift", vec![lref(ax)], lref(drift));
            let g = &spec.gridlines[i];
            self.funa("BLAxis/nGridlines", vec![lref(ax)], natv(g.len() as u64));
            for (gi, q) in g.iter().enumerate() {
                self.funa("BLAxis/gridline", vec![natv(gi as u64), lref(ax)], qv(*q));
            }
        }
        for (bi, cells) in spec.blocks.iter().enumerate() {
            let blk = self.fresh();
            self.funa("FamBlock/lattice", vec![lref(blk)], lref(bl));
            self.funa("FamBlock/index", vec![lref(blk)], natv(bi as u64));
            self.funa("FamBlock/nCells", vec![lref(blk)], natv(cells.len() as u64));
            for (ci, cell) in cells.iter().enumerate() {
                self.funa(
                    "FamBlock/cell",
                    vec![lref(blk), natv(ci as u64)],
                    natv(*cell),
                );
            }
            let proofs = &spec.facet_proofs[bi];
            let declared = spec.n_facets_override[bi].unwrap_or(proofs.len() as u64);
            self.funa("FamBlock/nFacets", vec![lref(blk)], natv(declared));
            for (fi, proof) in proofs.iter().enumerate() {
                self.funa(
                    "FamBlock/facetProof",
                    vec![lref(blk), natv(fi as u64)],
                    lref(*proof),
                );
            }
        }
        bl
    }

    /// A one-dimensional interval region atom: a fresh two-vertex
    /// complex at ambient dimension one, a simplex containing both
    /// vertices, an empty extension set anchored on it.
    fn interval_atom(&mut self, wire: u32, lo: (i64, u64), hi: (i64, u64)) -> u32 {
        let cx = self.fresh();
        self.funa("SimpC/n_vertices", vec![lref(cx)], natv(2));
        self.funa("SimpC/amb_dim", vec![lref(cx)], natv(1));
        self.funa("SimpC/coord", vec![lref(cx), natv(0), natv(0)], qv(lo));
        self.funa("SimpC/coord", vec![lref(cx), natv(0), natv(1)], qv(hi));
        let s = self.fresh();
        self.funa("Simplex/complex", vec![lref(s)], lref(cx));
        self.rela("Simplex/contains", vec![lref(s), natv(0)]);
        self.rela("Simplex/contains", vec![lref(s), natv(1)]);
        let ext = self.fresh();
        self.funa("ExtensionSet/simplex", vec![lref(ext)], lref(s));
        let t = self.ctor("TVar", vec![lref(wire)]);
        // Bytewise field order: S, simplex, t.
        self.ctor("FInRegion", vec![lref(ext), lref(s), lref(t)])
    }

    /// A facet-sign sequent proof: pre the conjunction of the given
    /// region atoms (a single atom stands alone), post
    /// `subst(drift) OP margin`.
    fn facet_proof_with_pre(
        &mut self,
        drift: &T,
        pinned_wire: u32,
        pinned_value: (i64, u64),
        upper: bool,
        margin: (i64, u64),
        pre_atoms: Vec<u32>,
    ) -> u32 {
        let p_term = subst(drift, pinned_wire, pinned_value);
        let l = self.term(&p_term);
        let m = self.ctor("TConst", vec![qv(margin)]);
        let atom = if upper { "FAtomLE" } else { "FAtomGE" };
        let post = self.ctor(atom, vec![lref(l), lref(m)]);
        let mut pre = pre_atoms[0];
        for a in &pre_atoms[1..] {
            pre = self.ctor("FAnd", vec![lref(pre), lref(*a)]);
        }
        let j = self.fresh();
        self.funa("Judgment/pre", vec![lref(j)], lref(pre));
        self.funa("Judgment/post", vec![lref(j)], lref(post));
        let proof = self.fresh();
        self.funa("Proof/concludes", vec![lref(proof)], lref(j));
        proof
    }

    /// The canonical minimal facet node: the pinned axis's full-arena
    /// atom as the sole pre conjunct (every free-axis atom absent —
    /// the licensed form).
    fn facet_proof(
        &mut self,
        drift: &T,
        wire: u32,
        arena: ((i64, u64), (i64, u64)),
        pinned_value: (i64, u64),
        upper: bool,
        margin: (i64, u64),
    ) -> u32 {
        let atom = self.interval_atom(wire, arena.0, arena.1);
        self.facet_proof_with_pre(drift, wire, pinned_value, upper, margin, vec![atom])
    }

    /// The product node: judgment, factor references, metadata flag.
    fn product(&mut self, left: u32, right: u32, comp: u32, flows_only: u64) -> u32 {
        let famj = self.fresh();
        self.funa("FamJudgment/lattice", vec![lref(famj)], lref(comp));
        let p = self.fresh();
        self.funa("PProductLattice/concludes", vec![lref(p)], lref(famj));
        self.funa("PProductLattice/left", vec![lref(p)], lref(left));
        self.funa("PProductLattice/right", vec![lref(p)], lref(right));
        self.funa("PProductLattice/flowsOnly", vec![lref(p)], natv(flows_only));
        p
    }
}

// ---------------------------------------------------------------------
// The Kalies–Wehbe worked witness (the golden and its mutant dials)
// ---------------------------------------------------------------------

/// Dials for the golden; each mutant flips exactly one.
#[derive(Clone, Copy, Default)]
struct Dials {
    margin_flip: bool,
    poly_skew: bool,
    slot_swap: bool,
    shared_wire: bool,
    grid_skew: bool,
    block_drop: bool,
    drift_leak: bool,
    famjudge_skew: bool,
    flows_only: u64,
}

/// Build the golden product body: two one-dimensional factors
/// (drifts `x − x·x` and `2·(y − y·y)`, cuts at 1/4 and 1/3, upper
/// cell blocks) and the three-block composite, composite facet slots
/// CITING the factor facet nodes.
fn kw_body(d: Dials) -> (Body, u32) {
    let mut b = Body::new();
    let wx = b.fresh();
    let wy = if d.shared_wire { wx } else { b.fresh() };
    let f1_base = sub(T::V(wx), mul(T::V(wx), T::V(wx)));
    let f1 = if d.drift_leak {
        add(f1_base.clone(), mul(T::C(0, 1), T::V(wy)))
    } else {
        f1_base
    };
    let f2 = mul(T::C(2, 1), sub(T::V(wy), mul(T::V(wy), T::V(wy))));

    let m1 = if d.margin_flip { (-3, 16) } else { (3, 16) };
    let v1 = if d.poly_skew { (1, 1) } else { (1, 4) };
    let n1 = b.facet_proof(&f1, wx, ((0, 1), (1, 1)), v1, false, m1);
    let n2 = b.facet_proof(&f2, wy, ((0, 1), (1, 1)), (1, 3), false, (4, 9));

    let l1 = b.lattice(&LatSpec::new(
        vec![wx],
        vec![f1.clone()],
        vec![vec![(0, 1), (1, 4), (1, 1)]],
        vec![vec![1]],
        vec![vec![n1]],
    ));
    let l2 = b.lattice(&LatSpec::new(
        vec![wy],
        vec![f2.clone()],
        vec![vec![(0, 1), (1, 3), (1, 1)]],
        vec![vec![1]],
        vec![vec![n2]],
    ));

    let comp_cut_x = if d.grid_skew { (1, 5) } else { (1, 4) };
    let mut comp_blocks = vec![vec![3], vec![2, 3], vec![1, 3]];
    let mut comp_proofs = vec![
        if d.slot_swap {
            vec![n2, n1]
        } else {
            vec![n1, n2]
        },
        vec![n1, n1],
        vec![n2, n2],
    ];
    if d.block_drop {
        comp_blocks.pop();
        comp_proofs.pop();
    }
    let lc = b.lattice(&LatSpec::new(
        vec![wx, wy],
        vec![f1, f2],
        vec![
            vec![(0, 1), comp_cut_x, (1, 1)],
            vec![(0, 1), (1, 3), (1, 1)],
        ],
        comp_blocks,
        comp_proofs,
    ));

    let comp_for_judgment = if d.famjudge_skew { l1 } else { lc };
    let p = b.product(l1, l2, comp_for_judgment, d.flows_only);
    (b, p)
}

// ---------------------------------------------------------------------
// blockLatticeWF: spec battery
// ---------------------------------------------------------------------

/// A well-formedness-only lattice: constant drifts, bare proof
/// elements in the facet slots (well-formedness never reads proof
/// structure).
fn wf_lattice(
    b: &mut Body,
    gridlines: Vec<Vec<(i64, u64)>>,
    blocks: Vec<Vec<u64>>,
    facet_counts: &[u64],
) -> u32 {
    let n_axes = gridlines.len();
    let wires: Vec<u32> = (0..n_axes).map(|_| b.fresh()).collect();
    let drifts: Vec<T> = (0..n_axes).map(|_| T::C(0, 1)).collect();
    let facet_proofs: Vec<Vec<u32>> = facet_counts
        .iter()
        .map(|n| (0..*n).map(|_| b.fresh()).collect())
        .collect();
    b.lattice(&LatSpec::new(
        wires,
        drifts,
        gridlines,
        blocks,
        facet_proofs,
    ))
}

#[test]
fn wf_kw_factor_holds() {
    let mut b = Body::new();
    let bl = wf_lattice(
        &mut b,
        vec![vec![(0, 1), (1, 4), (1, 1)]],
        vec![vec![1]],
        &[1],
    );
    assert_eq!(ev_elems("blockLatticeWF", &[bl], &b.rows()), Ok(true));
}

/// A named well-formedness case: the label and a builder returning
/// the lattice element to evaluate.
type WfCase = (&'static str, Box<dyn Fn(&mut Body) -> u32>);

#[test]
fn wf_decided_violations() {
    // Each case: (name, builder → lattice elem); every one must FAIL,
    // not refuse.
    let cases: Vec<WfCase> = vec![
        (
            "facet count off by one",
            Box::new(|b| wf_lattice(b, vec![vec![(0, 1), (1, 4), (1, 1)]], vec![vec![1]], &[2])),
        ),
        (
            "gridlines not strictly increasing",
            Box::new(|b| wf_lattice(b, vec![vec![(0, 1), (1, 1), (1, 4)]], vec![vec![1]], &[1])),
        ),
        (
            "single gridline",
            Box::new(|b| wf_lattice(b, vec![vec![(0, 1)]], vec![vec![0]], &[0])),
        ),
        (
            "improper block (the whole arena)",
            Box::new(|b| {
                wf_lattice(
                    b,
                    vec![vec![(0, 1), (1, 4), (1, 1)]],
                    vec![vec![0, 1]],
                    &[0],
                )
            }),
        ),
        (
            "cell out of range",
            Box::new(|b| wf_lattice(b, vec![vec![(0, 1), (1, 4), (1, 1)]], vec![vec![2]], &[0])),
        ),
        (
            "cells not strictly increasing",
            Box::new(|b| {
                wf_lattice(
                    b,
                    vec![vec![(0, 1), (1, 3), (2, 3), (1, 1)]],
                    vec![vec![1, 1]],
                    &[2],
                )
            }),
        ),
        (
            "duplicate stored blocks",
            Box::new(|b| {
                wf_lattice(
                    b,
                    vec![vec![(0, 1), (1, 3), (2, 3), (1, 1)]],
                    vec![vec![1], vec![1]],
                    &[2, 2],
                )
            }),
        ),
        (
            "zero stored blocks",
            Box::new(|b| wf_lattice(b, vec![vec![(0, 1), (1, 4), (1, 1)]], vec![], &[])),
        ),
        (
            "drift outside the scalar fragment",
            Box::new(|b| {
                let w = b.fresh();
                let proof = b.fresh();
                b.lattice(&LatSpec::new(
                    vec![w],
                    vec![T::Neg(Box::new(T::V(w)))],
                    vec![vec![(0, 1), (1, 4), (1, 1)]],
                    vec![vec![1]],
                    vec![vec![proof]],
                ))
            }),
        ),
        (
            "duplicate axis wires",
            Box::new(|b| {
                let w = b.fresh();
                let proofs: Vec<u32> = (0..2).map(|_| b.fresh()).collect();
                b.lattice(&LatSpec::new(
                    vec![w, w],
                    vec![T::C(0, 1), T::C(0, 1)],
                    vec![vec![(0, 1), (1, 2), (1, 1)], vec![(0, 1), (1, 2), (1, 1)]],
                    vec![vec![3]],
                    vec![proofs],
                ))
            }),
        ),
        (
            "axis index out of range",
            Box::new(|b| {
                // One declared axis whose index row says 1.
                let bl = b.fresh();
                b.funa("BlockLattice/nAxes", vec![lref(bl)], natv(1));
                b.funa("BlockLattice/nBlocks", vec![lref(bl)], natv(1));
                let ax = b.fresh();
                b.funa("BLAxis/lattice", vec![lref(ax)], lref(bl));
                b.funa("BLAxis/index", vec![lref(ax)], natv(1));
                bl
            }),
        ),
        (
            "duplicate block indices",
            Box::new(|b| {
                let bl = wf_lattice(
                    b,
                    vec![vec![(0, 1), (1, 3), (2, 3), (1, 1)]],
                    vec![vec![0], vec![2]],
                    &[1, 1],
                );
                // Rewrite the second block's index row is not possible
                // through the emitter; instead declare a THIRD block
                // element reusing index 0.
                let blk = b.fresh();
                b.funa("FamBlock/lattice", vec![lref(blk)], lref(bl));
                b.funa("FamBlock/index", vec![lref(blk)], natv(0));
                bl
            }),
        ),
    ];
    for (name, build) in cases {
        let mut b = Body::new();
        let bl = build(&mut b);
        assert_eq!(
            ev_elems("blockLatticeWF", &[bl], &b.rows()),
            Ok(false),
            "expected a decided violation for: {name}"
        );
    }
}

#[test]
fn wf_refusals() {
    // Missing nAxes row: structure undecidable.
    {
        let mut b = Body::new();
        let bl = b.fresh();
        b.funa("BlockLattice/nBlocks", vec![lref(bl)], natv(1));
        let verdict = ev_elems("blockLatticeWF", &[bl], &b.rows());
        assert!(verdict.is_err(), "missing nAxes must refuse: {verdict:?}");
    }
    // Missing gridline family entry.
    {
        let mut b = Body::new();
        let bl = b.fresh();
        b.funa("BlockLattice/nAxes", vec![lref(bl)], natv(1));
        b.funa("BlockLattice/nBlocks", vec![lref(bl)], natv(1));
        let ax = b.fresh();
        let w = b.fresh();
        b.funa("BLAxis/lattice", vec![lref(ax)], lref(bl));
        b.funa("BLAxis/index", vec![lref(ax)], natv(0));
        b.funa("BLAxis/wire", vec![lref(ax)], lref(w));
        let drift = b.term(&T::C(0, 1));
        b.funa("BLAxis/drift", vec![lref(ax)], lref(drift));
        b.funa("BLAxis/nGridlines", vec![lref(ax)], natv(3));
        b.funa("BLAxis/gridline", vec![natv(0), lref(ax)], qv((0, 1)));
        b.funa("BLAxis/gridline", vec![natv(2), lref(ax)], qv((1, 1)));
        let verdict = ev_elems("blockLatticeWF", &[bl], &b.rows());
        assert!(verdict.is_err(), "gridline gap must refuse: {verdict:?}");
    }
    // Conflicting axis index rows: ambiguity refuses (never picks).
    {
        let mut b = Body::new();
        let bl = b.fresh();
        b.funa("BlockLattice/nAxes", vec![lref(bl)], natv(1));
        b.funa("BlockLattice/nBlocks", vec![lref(bl)], natv(1));
        let ax = b.fresh();
        b.funa("BLAxis/lattice", vec![lref(ax)], lref(bl));
        b.funa("BLAxis/index", vec![lref(ax)], natv(0));
        b.funa("BLAxis/index", vec![lref(ax)], natv(1));
        let verdict = ev_elems("blockLatticeWF", &[bl], &b.rows());
        assert!(
            verdict.is_err(),
            "conflicting index must refuse: {verdict:?}"
        );
    }
    // A facet-proof slot filled with a literal instead of an element.
    {
        let mut b = Body::new();
        let bl = wf_lattice(
            &mut b,
            vec![vec![(0, 1), (1, 4), (1, 1)]],
            vec![vec![1]],
            &[1],
        );
        // Find the emitted block element by scanning is overkill: emit
        // a second lattice with the bad slot instead.
        let _ = bl;
        let bl2 = b.fresh();
        b.funa("BlockLattice/nAxes", vec![lref(bl2)], natv(1));
        b.funa("BlockLattice/nBlocks", vec![lref(bl2)], natv(1));
        let ax = b.fresh();
        let w = b.fresh();
        b.funa("BLAxis/lattice", vec![lref(ax)], lref(bl2));
        b.funa("BLAxis/index", vec![lref(ax)], natv(0));
        b.funa("BLAxis/wire", vec![lref(ax)], lref(w));
        let drift = b.term(&T::C(0, 1));
        b.funa("BLAxis/drift", vec![lref(ax)], lref(drift));
        b.funa("BLAxis/nGridlines", vec![lref(ax)], natv(3));
        for (gi, q) in [(0i64, 1u64), (1, 4), (1, 1)].iter().enumerate() {
            b.funa("BLAxis/gridline", vec![natv(gi as u64), lref(ax)], qv(*q));
        }
        let blk = b.fresh();
        b.funa("FamBlock/lattice", vec![lref(blk)], lref(bl2));
        b.funa("FamBlock/index", vec![lref(blk)], natv(0));
        b.funa("FamBlock/nCells", vec![lref(blk)], natv(1));
        b.funa("FamBlock/cell", vec![lref(blk), natv(0)], natv(1));
        b.funa("FamBlock/nFacets", vec![lref(blk)], natv(1));
        b.funa("FamBlock/facetProof", vec![lref(blk), natv(0)], natv(7));
        let verdict = ev_elems("blockLatticeWF", &[bl2], &b.rows());
        assert!(
            verdict.is_err(),
            "literal proof slot must refuse: {verdict:?}"
        );
    }
}

