#[test]
fn product_named_mutants_flip() {
    let mutants: Vec<(&str, Dials)> = vec![
        (
            "margin sign flipped",
            Dials {
                margin_flip: true,
                ..Dials::default()
            },
        ),
        (
            "post polynomial substituted at the wrong plane",
            Dials {
                poly_skew: true,
                ..Dials::default()
            },
        ),
        (
            "composite facet slots swapped",
            Dials {
                slot_swap: true,
                ..Dials::default()
            },
        ),
        (
            "factors share a wire",
            Dials {
                shared_wire: true,
                ..Dials::default()
            },
        ),
        (
            "composite gridline skewed",
            Dials {
                grid_skew: true,
                ..Dials::default()
            },
        ),
        (
            "composite block dropped",
            Dials {
                block_drop: true,
                ..Dials::default()
            },
        ),
        (
            "factor drift mentions the other factor's wire",
            Dials {
                drift_leak: true,
                ..Dials::default()
            },
        ),
        (
            "judgment lattice is the left factor",
            Dials {
                famjudge_skew: true,
                ..Dials::default()
            },
        ),
    ];
    for (name, dials) in mutants {
        let (b, p) = kw_body(dials);
        assert_eq!(
            ev_elems("productLatticeChecks", &[p], &b.rows()),
            Ok(false),
            "mutant must flip the verdict: {name}"
        );
    }
}

