#[test]
fn product_free_axis_atom_present_and_exact() {
    // A composite facet node that DOES carry the free-axis atom: for
    // the corner block {3}, the axis-0 lower facet at x = 1/4 with the
    // free y interval [1/3, 1] spelled out. Exact interval → holds;
    // skewed interval → fails.
    for (hi, expect) in [((1i64, 1u64), true), ((2, 3), false)] {
        let mut b = Body::new();
        let wx = b.fresh();
        let wy = b.fresh();
        let f1 = sub(T::V(wx), mul(T::V(wx), T::V(wx)));
        let f2 = mul(T::C(2, 1), sub(T::V(wy), mul(T::V(wy), T::V(wy))));
        // Factor nodes (minimal pre).
        let n1 = b.facet_proof(&f1, wx, ((0, 1), (1, 1)), (1, 4), false, (3, 16));
        let n2 = b.facet_proof(&f2, wy, ((0, 1), (1, 1)), (1, 3), false, (4, 9));
        // The composite's m-block axis-0 slot: full-arena pinned atom
        // plus an explicit free-axis atom on y.
        let pinned_atom = b.interval_atom(wx, (0, 1), (1, 1));
        let free_atom = b.interval_atom(wy, (1, 3), hi);
        let n1c = b.facet_proof_with_pre(
            &f1,
            wx,
            (1, 4),
            false,
            (3, 16),
            vec![pinned_atom, free_atom],
        );
        let l1 = b.lattice(&LatSpec::new(
            vec![wx],
            vec![f1.clone()],
            vec![vec![(0, 1), (1, 4), (1, 1)]],
            vec![vec![1]],
            vec![vec![n1]],
        ));
        let l2 = b.lattice(&LatSpec::new(
            vec![wy],
            vec![f2.clone()],
            vec![vec![(0, 1), (1, 3), (1, 1)]],
            vec![vec![1]],
            vec![vec![n2]],
        ));
        let lc = b.lattice(&LatSpec::new(
            vec![wx, wy],
            vec![f1, f2],
            vec![vec![(0, 1), (1, 4), (1, 1)], vec![(0, 1), (1, 3), (1, 1)]],
            vec![vec![3], vec![2, 3], vec![1, 3]],
            vec![vec![n1c, n2], vec![n1, n1], vec![n2, n2]],
        ));
        let p = b.product(l1, l2, lc, 0);
        assert_eq!(
            ev_elems("productLatticeChecks", &[p], &b.rows()),
            Ok(expect),
            "free-axis atom with hi = {hi:?}"
        );
    }
}

#[test]
fn product_refusals() {
    // An external facet-proof reference: the conclusion lives in
    // another body, so discharge is undecidable here.
    {
        let mut b = Body::new();
        let wx = b.fresh();
        let wy = b.fresh();
        let f1 = sub(T::V(wx), mul(T::V(wx), T::V(wx)));
        let f2 = mul(T::C(2, 1), sub(T::V(wy), mul(T::V(wy), T::V(wy))));
        let n2 = b.facet_proof(&f2, wy, ((0, 1), (1, 1)), (1, 3), false, (4, 9));
        let l1 = {
            // Hand-emit the left factor so its one facet slot can hold
            // an external ref.
            let bl = b.fresh();
            b.funa("BlockLattice/nAxes", vec![lref(bl)], natv(1));
            b.funa("BlockLattice/nBlocks", vec![lref(bl)], natv(1));
            let ax = b.fresh();
            b.funa("BLAxis/lattice", vec![lref(ax)], lref(bl));
            b.funa("BLAxis/index", vec![lref(ax)], natv(0));
            b.funa("BLAxis/wire", vec![lref(ax)], lref(wx));
            let drift = b.term(&f1.clone());
            b.funa("BLAxis/drift", vec![lref(ax)], lref(drift));
            b.funa("BLAxis/nGridlines", vec![lref(ax)], natv(3));
            for (gi, q) in [(0i64, 1u64), (1, 4), (1, 1)].iter().enumerate() {
                b.funa("BLAxis/gridline", vec![natv(gi as u64), lref(ax)], qv(*q));
            }
            let blk = b.fresh();
            b.funa("FamBlock/lattice", vec![lref(blk)], lref(bl));
            b.funa("FamBlock/index", vec![lref(blk)], natv(0));
            b.funa("FamBlock/nCells", vec![lref(blk)], natv(1));
            b.funa("FamBlock/cell", vec![lref(blk), natv(0)], natv(1));
            b.funa("FamBlock/nFacets", vec![lref(blk)], natv(1));
            b.funa(
                "FamBlock/facetProof",
                vec![lref(blk), natv(0)],
                Value::Ref(ElemRef::External {
                    dep_index: 0,
                    counter: 99,
                }),
            );
            bl
        };
        let n1 = b.facet_proof(&f1, wx, ((0, 1), (1, 1)), (1, 4), false, (3, 16));
        let l2 = b.lattice(&LatSpec::new(
            vec![wy],
            vec![f2.clone()],
            vec![vec![(0, 1), (1, 3), (1, 1)]],
            vec![vec![1]],
            vec![vec![n2]],
        ));
        let lc = b.lattice(&LatSpec::new(
            vec![wx, wy],
            vec![f1, f2],
            vec![vec![(0, 1), (1, 4), (1, 1)], vec![(0, 1), (1, 3), (1, 1)]],
            vec![vec![3], vec![2, 3], vec![1, 3]],
            vec![vec![n1, n2], vec![n1, n1], vec![n2, n2]],
        ));
        let p = b.product(l1, l2, lc, 0);
        let verdict = ev_elems("productLatticeChecks", &[p], &b.rows());
        assert!(
            verdict.is_err(),
            "external facet proof must refuse: {verdict:?}"
        );
    }
    // A proof without a conclusion row.
    {
        let (mut b, _) = kw_body(Dials::default());
        // Fresh minimal product whose left factor cites a bare proof.
        let wx = b.fresh();
        let wy = b.fresh();
        let f1 = T::C(0, 1);
        let f2 = T::C(0, 1);
        let bare = b.fresh();
        let l1 = b.lattice(&LatSpec::new(
            vec![wx],
            vec![f1.clone()],
            vec![vec![(0, 1), (1, 2), (1, 1)]],
            vec![vec![1]],
            vec![vec![bare]],
        ));
        let bares: Vec<u32> = (0..7).map(|_| b.fresh()).collect();
        let l2 = b.lattice(&LatSpec::new(
            vec![wy],
            vec![f2.clone()],
            vec![vec![(0, 1), (1, 2), (1, 1)]],
            vec![vec![1]],
            vec![vec![bares[0]]],
        ));
        let lc = b.lattice(&LatSpec::new(
            vec![wx, wy],
            vec![f1, f2],
            vec![vec![(0, 1), (1, 2), (1, 1)], vec![(0, 1), (1, 2), (1, 1)]],
            vec![vec![3], vec![2, 3], vec![1, 3]],
            vec![
                vec![bares[1], bares[2]],
                vec![bares[3], bares[4]],
                vec![bares[5], bares[6]],
            ],
        ));
        let p = b.product(l1, l2, lc, 0);
        let verdict = ev_elems("productLatticeChecks", &[p], &b.rows());
        assert!(
            verdict.is_err(),
            "bare facet proof must refuse: {verdict:?}"
        );
    }
}

// ---------------------------------------------------------------------
// The frozen cross-implementation corpus
// ---------------------------------------------------------------------

fn corpus() -> J {
    let raw = include_str!("fixtures/bllattice_pyref_corpus.json");
    serde_json::from_str(raw).expect("corpus parses")
}

fn j_q(v: &J) -> (i64, u64) {
    let a = v.as_array().expect("rational pair");
    (
        a[0].as_i64().expect("numerator"),
        a[1].as_u64().expect("denominator"),
    )
}

fn j_gridlines(v: &J) -> Vec<Vec<(i64, u64)>> {
    v.as_array()
        .expect("axes")
        .iter()
        .map(|axis| {
            axis.as_array()
                .expect("gridlines")
                .iter()
                .map(j_q)
                .collect()
        })
        .collect()
}

fn j_blocks(v: &J) -> Vec<Vec<u64>> {
    v.as_array()
        .expect("blocks")
        .iter()
        .map(|b| {
            b.as_array()
                .expect("cells")
                .iter()
                .map(|c| c.as_u64().expect("cell"))
                .collect()
        })
        .collect()
}

/// Per block, the python reference's facet triples (cell, axis, upper).
fn j_facets(v: &J) -> Vec<Vec<(u64, usize, bool)>> {
    v.as_array()
        .expect("facet families")
        .iter()
        .map(|f| {
            f.as_array()
                .expect("facets")
                .iter()
                .map(|t| {
                    let t = t.as_array().expect("facet triple");
                    (
                        t[0].as_u64().expect("cell"),
                        t[1].as_u64().expect("axis") as usize,
                        t[2].as_bool().expect("direction"),
                    )
                })
                .collect()
        })
        .collect()
}

#[test]
fn corpus_wf_counts_replay() {
    let c = corpus();
    for case in c["wf"].as_array().expect("wf cases") {
        let name = case["name"].as_str().expect("name");
        let gridlines = j_gridlines(&case["gridlines"]);
        let blocks = j_blocks(&case["blocks"]);
        let counts: Vec<u64> = j_facets(&case["facets"])
            .iter()
            .map(|f| f.len() as u64)
            .collect();
        // Python's facet counts in the declared slots → the evaluator's
        // own recompute must agree.
        let mut b = Body::new();
        let bl = wf_lattice(&mut b, gridlines.clone(), blocks.clone(), &counts);
        assert_eq!(
            ev_elems("blockLatticeWF", &[bl], &b.rows()),
            Ok(true),
            "corpus wf case must hold: {name}"
        );
        // And the count is load-bearing: one more must flip block 0.
        let mut skewed = counts.clone();
        skewed[0] += 1;
        let mut b2 = Body::new();
        let bl2 = wf_lattice(&mut b2, gridlines, blocks, &skewed);
        assert_eq!(
            ev_elems("blockLatticeWF", &[bl2], &b2.rows()),
            Ok(false),
            "skewed count must fail: {name}"
        );
    }
}

/// Emit one corpus lattice with real facet nodes generated from the
/// PYTHON facet list (never from a Rust enumeration).
#[allow(clippy::too_many_arguments)]
fn corpus_lattice(
    b: &mut Body,
    wires: &[u32],
    drifts: &[T],
    gridlines: &[Vec<(i64, u64)>],
    blocks: &[Vec<u64>],
    facets: &[Vec<(u64, usize, bool)>],
) -> u32 {
    // Decompose a row-major cell index (axis 0 slowest) — the corpus
    // documents the same convention the python reference used; the
    // EVALUATOR'S agreement with it is what the replay tests.
    let counts: Vec<u64> = gridlines.iter().map(|g| g.len() as u64 - 1).collect();
    let coords = |cell: u64| -> Vec<u64> {
        let mut out = vec![0u64; counts.len()];
        let mut rem = cell;
        for i in (0..counts.len()).rev() {
            out[i] = rem % counts[i];
            rem /= counts[i];
        }
        out
    };
    let mut proofs: Vec<Vec<u32>> = Vec::with_capacity(blocks.len());
    for facet_family in facets {
        let mut family = Vec::with_capacity(facet_family.len());
        for &(cell, axis, upper) in facet_family {
            let c = coords(cell)[axis] as usize;
            let g = &gridlines[axis];
            let pinned = if upper { g[c + 1] } else { g[c] };
            let margin = if upper { (-1, 1) } else { (1, 1) };
            let arena = (g[0], g[g.len() - 1]);
            family.push(b.facet_proof(&drifts[axis], wires[axis], arena, pinned, upper, margin));
        }
        proofs.push(family);
    }
    b.lattice(&LatSpec::new(
        wires.to_vec(),
        drifts.to_vec(),
        gridlines.to_vec(),
        blocks.to_vec(),
        proofs,
    ))
}

#[test]
fn corpus_product_replay() {
    let c = corpus();
    for case in c["product"].as_array().expect("product cases") {
        let name = case["name"].as_str().expect("name");
        let mut b = Body::new();
        type Side = (
            Vec<Vec<(i64, u64)>>,
            Vec<Vec<u64>>,
            Vec<Vec<(u64, usize, bool)>>,
        );
        let sides: Vec<Side> = ["left", "right", "composite"]
            .iter()
            .map(|side| {
                let s = &case[*side];
                (
                    j_gridlines(&s["gridlines"]),
                    j_blocks(&s["blocks"]),
                    j_facets(&s["facets"]),
                )
            })
            .collect();
        let n_left_axes = sides[0].0.len();
        let n_axes_total = n_left_axes + sides[1].0.len();
        assert_eq!(sides[2].0.len(), n_axes_total, "corpus axes consistent");
        // One wire and one linear drift per composite axis; the
        // factors reuse the same wires (left's prefix, right's
        // suffix) so the product obligations are exercised for real.
        let wires: Vec<u32> = (0..n_axes_total).map(|_| b.fresh()).collect();
        let drifts: Vec<T> = wires.iter().map(|w| sub(T::C(1, 2), T::V(*w))).collect();
        let l = corpus_lattice(
            &mut b,
            &wires[..n_left_axes],
            &drifts[..n_left_axes],
            &sides[0].0,
            &sides[0].1,
            &sides[0].2,
        );
        let r = corpus_lattice(
            &mut b,
            &wires[n_left_axes..],
            &drifts[n_left_axes..],
            &sides[1].0,
            &sides[1].1,
            &sides[1].2,
        );
        let comp = corpus_lattice(
            &mut b,
            &wires,
            &drifts,
            &sides[2].0,
            &sides[2].1,
            &sides[2].2,
        );
        let p = b.product(l, r, comp, 0);
        assert_eq!(
            ev_elems("productLatticeChecks", &[p], &b.rows()),
            Ok(true),
            "corpus product case must hold: {name}"
        );
    }
}

